ALTER TABLE "wb_next"."media_assets" DROP CONSTRAINT "media_size";--> statement-breakpoint
ALTER TABLE "wb_next"."native_marketing_media" DROP CONSTRAINT "native_media_state";--> statement-breakpoint
ALTER TABLE "wb_next"."media_assets" ADD CONSTRAINT "media_size" CHECK ("wb_next"."media_assets"."byte_length" between 1 and 67108864 and "wb_next"."media_assets"."width" between 16 and 4096 and "wb_next"."media_assets"."height" between 16 and 4096 and "wb_next"."media_assets"."duration_ms" between 500 and 10600);--> statement-breakpoint
ALTER TABLE "wb_next"."native_marketing_media" ADD CONSTRAINT "native_media_state" CHECK (("wb_next"."native_marketing_media"."state" = 'transcribing' and "wb_next"."native_marketing_media"."revision" = 0 and "wb_next"."native_marketing_media"."confirmed_cues" is null and "wb_next"."native_marketing_media"."confirmation_request_key" is null and "wb_next"."native_marketing_media"."confirmation_hash" is null) or ("wb_next"."native_marketing_media"."state" = 'review' and "wb_next"."native_marketing_media"."revision" = 1 and "wb_next"."native_marketing_media"."confirmed_cues" is null and "wb_next"."native_marketing_media"."confirmation_request_key" is null and "wb_next"."native_marketing_media"."confirmation_hash" is null) or ("wb_next"."native_marketing_media"."state" = 'ready' and "wb_next"."native_marketing_media"."revision" = 2 and "wb_next"."native_marketing_media"."confirmed_cues" is not null and "wb_next"."native_marketing_media"."confirmation_request_key" is not null and "wb_next"."native_marketing_media"."confirmation_hash" is not null and "wb_next"."native_marketing_media"."confirmation_hash" ~ '^[a-f0-9]{64}$'));